package com.fse.country;
import java.net.URI; import java.util.List; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/countries") public class CountryController { private final CountryRepository countries; public CountryController(CountryRepository countries) { this.countries = countries; } @GetMapping public List<Country> all() { return countries.findAll(); } @GetMapping("/{code}") public Country byCode(@PathVariable String code) { return countries.findById(code.toUpperCase()).orElseThrow(() -> new CountryNotFoundException(code)); } @GetMapping("/search") public List<Country> search(@RequestParam String name) { return countries.findByNameContainingIgnoreCase(name); } @PostMapping public ResponseEntity<Country> add(@Valid @RequestBody Country country) { Country saved = countries.save(country); return ResponseEntity.created(URI.create("/countries/" + saved.getCode())).body(saved); } }
